158	        await using (var output = new FileStream(destination, FileMode.CreateNew, FileAccess.Write, FileShare.None, 81920, useAsync: true))
159	        await using (var input = await response.Content.ReadAsStreamAsync(CancellationToken.None).ConfigureAwait(false))
160	            await input.CopyToAsync(output, CancellationToken.None).ConfigureAwait(false);
161	
162	        await using var artifact = new FileStream(destination, FileMode.Open, FileAccess.Read, FileShare.Read, 81920, useAsync: true);
