174	/// <summary>
175	/// TR-MCP-EMBEDDING-001 model-backed-assertions: resolves the ONNX Runtime native asset shipped under the test
176	/// output's runtime-specific folder before any test can initialize the dependency's native-method type.
177	/// </summary>
178	/// <remarks>
179	/// 2026-11-09: Microsoft.ML.OnnxRuntime 1.24.1 imports <c>onnxruntime.dll</c>; the portable Linux test host does not
180	/// map that name to its copied <c>runtimes/linux-*/native/libonnxruntime.so</c> asset without an explicit resolver.
181	/// The module initializer makes the positive fixture and corrupt-model control independent of xUnit execution order.
182	/// </remarks>
183	internal static class EmbeddingNativeRuntime
184	{
185	    /// <summary>Registers the integration-test assembly's resolver before xUnit constructs any test or fixture.</summary>
186	    [ModuleInitializer]
187	    internal static void Configure()
188	        => NativeLibrary.SetDllImportResolver(typeof(InferenceSession).Assembly, Resolve);
189	
190	    /// <summary>Loads the package's native ONNX Runtime asset for the current supported host.</summary>
191	    /// <param name="libraryName">The unmanaged import name requested by ONNX Runtime.</param>
192	    /// <param name="assembly">The managed ONNX Runtime assembly requesting the import.</param>
193	    /// <param name="searchPath">The dependency's requested native library search path.</param>
194	    /// <returns>The loaded native handle, or zero for unrelated imports and unsupported hosts.</returns>
195	    private static IntPtr Resolve(string libraryName, Assembly assembly, DllImportSearchPath? searchPath)
196	    {
197	        if (!string.Equals(libraryName, "onnxruntime.dll", StringComparison.OrdinalIgnoreCase))
198	            return IntPtr.Zero;
199	
200	        var architecture = RuntimeInformation.ProcessArchitecture switch
201	        {
202	            Architecture.X64 => "x64",
203	            Architecture.Arm64 => "arm64",
204	            _ => null,
205	        };
206	        var platform = OperatingSystem.IsWindows() ? "win" : OperatingSystem.IsLinux() ? "linux" : OperatingSystem.IsMacOS() ? "osx" : null;
207	        var fileName = OperatingSystem.IsWindows() ? "onnxruntime.dll" : OperatingSystem.IsLinux() ? "libonnxruntime.so" : "libonnxruntime.dylib";
208	        if (architecture is null || platform is null)
209	            return IntPtr.Zero;
210	
211	        var path = Path.Combine(AppContext.BaseDirectory, "runtimes", $"{platform}-{architecture}", "native", fileName);
212	        return File.Exists(path) ? NativeLibrary.Load(path, assembly, searchPath) : IntPtr.Zero;
213	    }
214	}
