221	{
222	    /// <summary>Gets the exception from the most recent product log entry that carried one.</summary>
223	    internal Exception? LastException { get; private set; }
224	
225	    /// <summary>Gets the formatted message from the most recent product log entry.</summary>
226	    internal string? LastMessage { get; private set; }
227	
228	    /// <inheritdoc />
229	    public IDisposable? BeginScope<TState>(TState state)
230	        where TState : notnull
231	        => null;
232	
233	    /// <inheritdoc />
234	    public bool IsEnabled(LogLevel logLevel) => true;
235	
236	    /// <inheritdoc />
237	    public void Log<TState>(
238	        LogLevel logLevel,
239	        EventId eventId,
240	        TState state,
241	        Exception? exception,
242	        Func<TState, Exception?, string> formatter)
243	    {
244	        ArgumentNullException.ThrowIfNull(formatter);
245	        LastMessage = formatter(state, exception);
246	        if (exception is not null)
247	            LastException = exception;
248	    }
249	}
