    /// <summary>Creates a fixture with a new unique root under the host's temporary directory.</summary>
    public EmbeddingModelFixture()
        => RootPath = Path.Combine(Path.GetTempPath(), $"qbrainai-embedding-model-{Guid.NewGuid():N}");

