501	        /// make ToolRoot fail the nested-ancestor assertions.
502	        /// </summary>
503	        private static string ResolveCleanFixtureTempRoot()
504	        {
505	            var temp = Path.GetTempPath();
506	            var marker = Path.DirectorySeparatorChar + ".mcpServer" + Path.DirectorySeparatorChar;
507	            var normalized = temp.Replace(Path.AltDirectorySeparatorChar, Path.DirectorySeparatorChar);
508	            if (normalized.IndexOf(marker, StringComparison.OrdinalIgnoreCase) >= 0
